const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));export function oceanProgress(u,count=4,reducedMotion=!1){const end=Math.max(0,count-1),progress=clamp(Number.isFinite(u)?u:0,0,end);if(reducedMotion||progress>=.25)return progress;const t=progress/.25;return .25*t*t*(2-t)}export function oceanPanelState({index,progress,width,reducedMotion=!1,count=4}){const end=Math.max(0,count-1),p=clamp(Number.isFinite(progress)?progress:0,0,end);if(reducedMotion)return{x:0,visible:index===Math.round(p),opacity:1};const viewportWidth=Math.max(1,Number.isFinite(width)?width:1),x=(index-p)*viewportWidth,overscan=1,visible=x<=viewportWidth+overscan&&x+viewportWidth>=-overscan;return{x,visible,opacity:1}}